
(function () {
  const D = {"SE": {"ui": {"btn": "Frågor?", "title": "Fråga Exitkompass", "hello": "Hej! Jag svarar på vanliga frågor om värdering, rapporten och hur Exitkompass fungerar. Skriv en fråga eller välj ett förslag.", "ph": "Skriv din fråga…", "send": "Skicka", "close": "Stäng", "rel": "Relaterade frågor:", "sugg": "Vanliga frågor:", "none": "Jag hittar inget säkert svar på det. Prova att formulera om frågan, välj en av de vanliga frågorna, eller mejla kontakt@exitkompass.se.", "note": "Automatiska svar från våra vanliga frågor – inte rådgivning."}, "kb": [{"q": "Hur väljer ni de multiplar som används?", "a": "Basmultipeln för EV/EBITDA per bransch och justeringen för storlek kommer från Dealsuite Nordic M&A Monitor, en halvårsvis undersökning bland nordiska M&A-rådgivare om genomförda affärer i bolag med 1–200 MEUR i omsättning. I den senaste utgåvan (augusti 2026) ligger branschsnitten mellan 3,8x (detaljhandel) och 7,9x (mjukvara), och multipeln stiger med storleken: cirka 3,6x vid en EBITDA på 0,2 MEUR och 7,2x vid 10 MEUR. Vård och omsorg samt healthtech är Adscos bedömning, eftersom Dealsuite redovisar vård och läkemedel tillsammans. Därefter justerar vi för bolagets egenskaper: tillväxt, resultatutveckling, ägarberoende, ledning, kundkoncentration, återkommande intäkter, rapportering, skriftliga avtal och riskflaggor i årsredovisningen, samt för styrräntan (högst ±0,6x), konjunkturen i branschen (±0,25x) och marginalen jämfört med branschen enligt SCB eller SSB. De justeringarna är Adscos bedömning. Multipeln blir aldrig lägre än 2,0x. EV/EBIT räknas fram ur EBITDA-multipeln, EV/omsättning har egna nivåer, och metoderna vägs ihop (resultatdelen 60 % EBITDA och 40 % EBIT, omsättningen 20–50 % beroende på marginal). Argos Index visas som jämförelse men påverkar inte multipeln.", "k": "välja väljer valt multipel multiplar multipeln basmultipel bransch nivå hur sätts bestäms varifrån kommer källa dealsuite databas underlag"}, {"q": "Hur fungerar Exitkompass?", "a": "Ange organisationsnummer eller företagsnamn. Vi hämtar årsredovisningarna och fyller i siffrorna. Du kontrollerar siffrorna och svarar på sju frågor om bland annat kunder, avtal och ägarberoende. Sedan får du direkt ett värdeintervall, en poäng för exitberedskap och de åtgärder som höjer värdet mest. Det tar ungefär tre minuter.", "k": "fungerar hur gör jag börja starta steg använda verktyget"}, {"q": "Vad ingår i rapporten?", "a": "Rapporten är en PDF från Adsco Capital Partners med punktvärdering och scenarier, känslighetsanalys, multipelbrygga och normaliserad EBITDA, alla köparens fynd med åtgärder, värdeskapandeplan på 12–24 månader, strategiskt värde, köpartyper, affärsstruktur, checklista för due diligence och försäljningsprocessen. Den granskas av en senior rådgivare.", "k": "rapport ingår innehåll pdf får jag"}, {"q": "Hur snabbt får jag rapporten?", "a": "Rapporten levereras inom 1–2 arbetsdagar efter beställning, granskad av en senior rådgivare. Ingen betalning sker vid beställningen; faktura skickas med rapporten med 10 dagars betalningsvillkor.", "k": "leverans snabbt när tid dagar leveranstid faktura betalning betala lång tid tar rapporten leveranstid"}, {"q": "Vilka källor använder ni?", "a": "Årsredovisningar från Bolagsverket och nyckeltal från Allabolag (UC AB) för svenska bolag, Brønnøysundregistrene för norska. Branschjämförelser från SCB och SSB, konjunkturläget från Konjunkturinstitutet och SSB, styrräntan från Riksbanken och Norges Bank, och marknadsläget för onoterade bolag från Argos Index.", "k": "källor data varifrån hämtar scb ssb bolagsverket riksbanken argos konjunkturinstitutet"}, {"q": "Vad är strategiskt värde?", "a": "Strategiskt värde är det en köpare kan betala utöver det finansiella värdet när bolaget ger synergier, till exempel nya kunder, marknader, produkter, teknik eller kompetens. Exitkompass bedömer det strategiska intresset som lågt, visst eller högt utifrån bransch, återkommande intäkter, tillväxt, marginal, kundspridning och aktiva köpare. Påslaget ingår inte i värderingen och förutsätter rätt köpare.", "k": "strategiskt värde synergi synergier strategisk köpare premie påslag"}, {"q": "Vad är EBITDA och normaliserad EBITDA?", "a": "EBITDA är rörelseresultatet före av- och nedskrivningar. Normaliserad EBITDA justerar för sådant som inte återkommer hos en ny ägare: engångskostnader läggs tillbaka och ägarlönen justeras till vad en anställd VD skulle kosta. Åren viktas 1:2:3 med störst vikt på det senaste.", "k": "ebitda normaliserad normalisering rörelseresultat avskrivningar ägarlön"}, {"q": "Kan jag värdera ett norskt bolag?", "a": "Ja. Välj Norge med flaggorna uppe på sidan. Språket väljer du separat i språkväljaren, så du kan till exempel värdera ett norskt bolag på svenska eller engelska.", "k": "norskt norge land språk engelska byta"}, {"q": "Hur når jag Sture Stölen?", "a": "Sture Stölen är grundande partner på Adsco Capital Partners. Du når honom direkt på sture@exitkompass.se.", "k": "sture stölen stølen stoelen grundare grundande partner mejl epost e-post adress"}, {"q": "Hur kontaktar jag er?", "a": "Du når Adsco Capital Partners på kontakt@exitkompass.se, eller grundande partner Sture Stölen direkt på sture@exitkompass.se. Funderar du på att sälja kan du boka ett kostnadsfritt, konfidentiellt möte med en partner – större bolag får erbjudandet direkt i resultatet.", "k": "kontakt kontakta mejl epost e-post adress telefon möte boka partner rådgivare"}, {"q": "Hur påverkar räntan värderingen?", "a": "Multiplarna justeras för styrräntan. När räntan är hög blir finansiering dyrare och köpare betalar lägre multiplar, och tvärtom. Justeringen är högst ±0,6x på multipeln.", "k": "ränta styrränta riksbanken påverkar multipel"}, {"q": "Hur exakt är värderingen?", "a": "Det är en indikativ värdering baserad på förenklade marknadsmultiplar och de uppgifter som hämtas eller lämnas. Det faktiska priset beror på köparen, affärsstrukturen, rörelsekapitalet och utfallet av due diligence. Se den som en första bedömning, inte som ett värderingsutlåtande.", "k": "exakt säker träffsäker stämmer pålitlig indikativ"}, {"q": "Vad är mitt företag värt?", "a": "I praktiken är ett företag värt det en köpare är beredd att betala. För små och medelstora onoterade bolag utgår man oftast från rörelseresultatet före avskrivningar (EBITDA) och multiplicerar med en multipel som beror på bransch, storlek och risk. I Exitkompass ligger grundmultiplerna mellan cirka 4 och 8,5 gånger EBITDA beroende på bransch, enligt Dealsuite Nordic M&A Monitor, som sammanställer nordiska M&A-rådgivares affärer. Mindre bolag värderas lägre än större, och därefter justeras för bolagets egna styrkor och svagheter.", "k": "värt värde värdera värdering"}, {"q": "Hur räknar Exitkompass fram värderingen?", "a": "Vi räknar med tre multiplar – EV/EBITDA, EV/EBIT och EV/omsättning – på ett viktat genomsnitt av de senaste årens resultat, med justeringar för kundkoncentration, andel återkommande intäkter, ägarberoende, tillväxt, avtal och rapportering. Vid låga marginaler väger omsättningen tyngre. Multiplarna följer också räntenivån, konjunkturen i branschen och bolagets marginal jämfört med branschen. Vi läser också texten i årsredovisningen och revisionsberättelsen; till exempel sänker en revisorsanmärkning om fortsatt drift multipeln. Till sist läggs nettokassan till för att få aktievärdet.", "k": ""}, {"q": "Vilka multiplar använder Exitkompass – EBITDA, EBIT eller omsättning?", "a": "Alla tre, eftersom det är så köpare räknar vid företagsförvärv. EV/EBITDA är vanligast för små och medelstora bolag. EV/EBIT ger en mer rättvisande bild för kapitalkrävande bolag med stora avskrivningar, och EV/omsättning används när lönsamheten är låg eller tillfälligt svag. Resultatdelen vägs 60 % på EBITDA och 40 % på EBIT, och omsättningen får 20–50 % beroende på marginalen. I resultatet ser du multipeln och värdet för varje metod.", "k": ""}, {"q": "Hur värderas ett aktiebolag när man ska sälja det?", "a": "Vid en försäljning värderas aktiebolaget utifrån vad en köpare är beredd att betala: det normaliserade resultatet de senaste åren gånger en branschmultipel, justerat för risk och kvalitet. Därefter läggs kassan till och räntebärande skulder dras av, så får man värdet på aktierna. Exitkompass räknar ut detta gratis och visar vad som höjer värdet inför en försäljning.", "k": ""}, {"q": "Vad är skillnaden mellan företagsvärde och aktievärde?", "a": "Företagsvärdet (enterprise value) är värdet på själva verksamheten, oberoende av hur den är finansierad. Aktievärdet är det ägarna får: företagsvärdet plus kassa minus räntebärande skulder. Exitkompass visar båda.", "k": ""}, {"q": "Vad höjer värdet inför en försäljning?", "a": "Köpare betalar mer för bolag med spridda och återkommande intäkter, som fungerar utan ägaren, har skriftliga avtal med kunder och nyckelpersoner, växer stabilt och har en tydlig och tillförlitlig finansiell rapportering. Exitkompass visar vilka av dessa åtgärder som påverkar just ditt bolag mest.", "k": ""}, {"q": "Kan jag använda värderingen vid bodelning, bouppteckning eller tvist?", "a": "Nej. Exitkompass är byggt för försäljning och visar vad en köpare kan tänkas betala för bolaget, det vill säga marknadsvärdet vid fortsatt drift baserat på multiplar. Vid bodelning, bouppteckning, arvskifte, tvister, inlösen av minoritetsaktier eller skatteärenden används ofta andra metoder, till exempel substansvärde, och det krävs en formell värdering. Vill du sälja nu eller om några år är Exitkompass rätt verktyg.", "k": ""}, {"q": "Vilka uppgifter behöver jag?", "a": "Organisationsnummer eller företagsnamn räcker för att komma igång. För svenska bolag hämtar vi digitalt inlämnade årsredovisningar från Bolagsverket och nyckeltal från Allabolag; för norska bolag hämtar vi uppgifter från Brønnøysundregistren. Saknas årsredovisningar kan du ladda upp dem som PDF. Därefter svarar du på sju frågor om verksamheten.", "k": "behöver ladda upp uppladdning årsredovisning dokument underlag"}, {"q": "Vad kostar det?", "a": "Snabbvärderingen är gratis och kräver ingen registrering. Den fullständiga rapporten kostar 2 995 kr exkl. moms och rapport med genomgång tillsammans med en partner 6 995 kr exkl. moms. Rapporten levereras inom 1–2 arbetsdagar och faktureras tillsammans med rapporten med 10 dagars betalningsvillkor.", "k": "pris priser kostnad kostar betala avgift gratis kronor"}, {"q": "Hanteras mina uppgifter konfidentiellt?", "a": "Ja. Det mesta vi hämtar, som årsredovisningar och bokslutssiffror, är offentlig information. Det du själv fyller i och de dokument du laddar upp, till exempel affärsplan, budget och månadsrapporter, används bara för att ta fram din värdering och delas aldrig med någon. Du kan när som helst be oss radera dem.", "k": "säkra säker säkert sekretess konfidentiell dokument uppgifter data radera gdpr delas"}, {"q": "Bygger värderingen på historiska siffror eller på budget?", "a": "På historiska siffror från årsredovisningarna, om inget annat laddas upp. Laddar du upp månadsrapporter, budget eller affärsplan vägs de in i rapporten. Månadsrapporterna ger de senaste tolv månaderna, som får störst vikt i resultatbasen. Budgeten ger ett tillväxtvärde som vägs in med 20 %, plus 5 % om en affärsplan förklarar den och plus 10 % om utfallet hittills i år följer budgeten. Ligger utfallet mer än 15 % efter dras 10 % av, och växer budgeten mycket snabbare än historiken halveras vikten. Vikten är högst 35 %, eftersom köpare främst betalar för bevisat resultat.", "k": "historiska historik budget prognos affärsplan månadsrapport månadsrapporter ltm tillväxt framtid viktning viktas vägs"}, {"q": "Passar Exitkompass för stora bolag och koncerner?", "a": "Exitkompass är byggt för små och medelstora bolag med en omsättning upp till cirka 500 MSEK, där multiplar för onoterade bolag ger en rimlig första bedömning. Mindre koncerner värderas på koncernens siffror. För större bolag och koncerner styrs värdet av noterade jämförelsebolag och strategiska transaktioner, så där visar verktyget ingen automatisk värdering utan erbjuder i stället ett kostnadsfritt möte med en partner på Adsco Capital Partners.", "k": "stort stora storlek koncern koncerner storföretag miljarder gräns maxstorlek"}, {"q": "Fungerar Exitkompass för norska bolag?", "a": "Ja. Den norska versionen finns på exitkompass.se/no och använder norska registeruppgifter och norska kronor.", "k": "norge norskt norska"}, {"q": "Kostar det något att värdera företaget?", "a": "Nej. Den indikativa värderingen i Exitkompass är gratis och kräver ingen registrering. En fullständig rapport med känslighetsanalys och värdeskapandeplan kan beställas mot avgift.", "k": ""}, {"q": "Hur lång tid tar det?", "a": "Några minuter. Siffrorna hämtas automatiskt, och du svarar på sju frågor om verksamheten.", "k": ""}, {"q": "Hur många gånger vinsten är ett företag värt?", "a": "Det beror på bransch, storlek och risk. Små onoterade bolag säljs ofta för cirka 3–8 gånger EBITDA. Rätt multipel för ditt bolag beror på faktorer som ägarberoende, kundspridning och tillväxt.", "k": ""}, {"q": "Räknar man på vinst före eller efter skatt?", "a": "Köpare räknar normalt på rörelseresultatet, före finansiella poster och skatt: EBITDA (före avskrivningar) eller EBIT (efter avskrivningar). Det gör det möjligt att jämföra bolag oberoende av hur de är finansierade.", "k": ""}, {"q": "Vad kostar det att sälja ett aktiebolag?", "a": "Kostnaden beror på storlek och komplexitet. Rådgivare tar ofta ett fast arvode och en framgångsbaserad avgift. Dessutom tillkommer kostnader för juridik och due diligence.", "k": ""}, {"q": "Hur lång tid tar en företagsförsäljning?", "a": "En försäljningsprocess tar ofta sex till tolv månader från förberedelse till tillträde. Förberedelserna som höjer värdet bör påbörjas ett till två år innan.", "k": ""}], "stop": ["jag", "du", "vi", "ni", "de", "det", "den", "en", "ett", "och", "att", "är", "som", "för", "på", "i", "av", "med", "till", "om", "hur", "vad", "vilka", "vilken", "vilket", "kan", "ska", "har", "mitt", "min", "mina", "ditt", "din", "er", "ert", "era", "man", "när", "var", "varför", "finns", "får", "gör", "blir", "eller", "också", "inte", "så"]}, "NO": {"ui": {"btn": "Spørsmål?", "title": "Spør Exitkompass", "hello": "Hei! Jeg svarer på vanlige spørsmål om verdivurdering, rapporten og hvordan Exitkompass fungerer. Skriv et spørsmål eller velg et forslag.", "ph": "Skriv spørsmålet ditt…", "send": "Send", "close": "Lukk", "rel": "Relaterte spørsmål:", "sugg": "Vanlige spørsmål:", "none": "Jeg finner ikke et sikkert svar på det. Prøv å formulere spørsmålet annerledes, velg et av de vanlige spørsmålene, eller send e-post til kontakt@exitkompass.se.", "note": "Automatiske svar fra våre vanlige spørsmål – ikke rådgivning."}, "kb": [{"q": "Hvordan velger dere multiplene som brukes?", "a": "Basismultippelen for EV/EBITDA per bransje og justeringen for størrelse kommer fra Dealsuite Nordic M&A Monitor, en halvårlig undersøkelse blant nordiske M&A-rådgivere om gjennomførte transaksjoner i selskaper med 1–200 MEUR i omsetning. I den siste utgaven (august 2026) ligger bransjesnittene mellom 3,8x (detaljhandel) og 7,9x (programvare), og multippelen stiger med størrelsen: rundt 3,6x ved EBITDA på 0,2 MEUR og 7,2x ved 10 MEUR. Helse og omsorg samt helseteknologi er Adscos vurdering, fordi Dealsuite rapporterer helse og legemidler samlet. Deretter justerer vi for selskapets egenskaper: vekst, resultatutvikling, eieravhengighet, ledelse, kundekonsentrasjon, gjentakende inntekter, rapportering, skriftlige avtaler og risikoflagg i årsregnskapet, samt for styringsrenten (maksimalt ±0,6x), konjunkturen i bransjen (±0,25x) og marginen sammenlignet med bransjen ifølge SSB eller SCB. Disse justeringene er Adscos vurdering. Multippelen blir aldri lavere enn 2,0x. EV/EBIT regnes ut fra EBITDA-multippelen, EV/omsetning har egne nivåer, og metodene vektes sammen (resultatdelen 60 % EBITDA og 40 % EBIT, omsetningen 20–50 % avhengig av margin). Argos Index vises som sammenligning, men påvirker ikke multippelen.", "k": "velge velger valgt multippel multipler multiplene basismultippel bransje nivå hvordan settes bestemmes hvor kommer kilde dealsuite database grunnlag"}, {"q": "Hvordan fungerer Exitkompass?", "a": "Oppgi organisasjonsnummer eller selskapsnavn. Vi henter regnskapstallene og fyller dem inn. Du kontrollerer tallene og svarer på sju spørsmål om blant annet kunder, avtaler og eieravhengighet. Deretter får du med en gang et verdiintervall, en poengsum for salgsklarhet og tiltakene som øker verdien mest. Det tar omtrent tre minutter.", "k": "fungerer hvordan begynne starte steg bruke verktøyet"}, {"q": "Hva er med i rapporten?", "a": "Rapporten er en PDF fra Adsco Capital Partners med punktverdi og scenarioer, sensitivitetsanalyse, multippelbro og normalisert EBITDA, alle kjøperens funn med tiltak, verdiskapingsplan for 12–24 måneder, strategisk verdi, kjøpertyper, transaksjonsstruktur, sjekkliste for due diligence og salgsprosessen. Den gjennomgås av en senior rådgiver.", "k": "rapport innhold pdf får jeg med"}, {"q": "Hvor raskt får jeg rapporten?", "a": "Rapporten leveres innen 1–2 virkedager etter bestilling, gjennomgått av en senior rådgiver. Du betaler ikke ved bestilling; faktura sendes med rapporten med 10 dagers betalingsfrist.", "k": "levering raskt når tid dager leveringstid faktura betaling betale lang tid tar rapporten leveringstid"}, {"q": "Hvilke kilder bruker dere?", "a": "Regnskapstall fra Brønnøysundregistrene for norske selskaper, og årsredovisninger fra Bolagsverket og nøkkeltall fra Allabolag (UC AB) for svenske. Bransjesammenligninger fra SSB og SCB, konjunktur fra SSB og Konjunkturinstitutet, styringsrenten fra Norges Bank og Riksbanken, og markedet for unoterte selskaper fra Argos Index.", "k": "kilder data hvor henter ssb scb brønnøysund norges bank argos"}, {"q": "Hva er strategisk verdi?", "a": "Strategisk verdi er det en kjøper kan betale i tillegg til den finansielle verdien når selskapet gir synergier, for eksempel nye kunder, markeder, produkter, teknologi eller kompetanse. Exitkompass vurderer den strategiske interessen som lav, noe eller høy ut fra bransje, gjentakende inntekter, vekst, margin, kundespredning og aktive kjøpere. Påslaget er ikke med i verdivurderingen og forutsetter riktig kjøper.", "k": "strategisk verdi synergi synergier strategisk kjøper premie påslag"}, {"q": "Hva er EBITDA og normalisert EBITDA?", "a": "EBITDA er driftsresultatet før av- og nedskrivninger. Normalisert EBITDA justerer for det som ikke gjentar seg hos en ny eier: engangskostnader legges tilbake og eierlønnen justeres til hva en ansatt daglig leder ville kostet. Årene vektes 1:2:3 med størst vekt på det siste.", "k": "ebitda normalisert normalisering driftsresultat avskrivninger eierlønn"}, {"q": "Kan jeg verdsette et svensk selskap?", "a": "Ja. Velg Sverige med flaggene øverst på siden. Språket velger du separat i språkvelgeren, så du kan for eksempel verdsette et svensk selskap på norsk eller engelsk.", "k": "svensk sverige land språk engelsk bytte"}, {"q": "Hvordan når jeg Sture Stölen?", "a": "Sture Stölen er grunnlegger og partner i Adsco Capital Partners. Du når ham direkte på sture@exitkompass.se.", "k": "sture stölen stølen stoelen grunnlegger partner e-post epost adresse"}, {"q": "Hvordan kontakter jeg dere?", "a": "Du når Adsco Capital Partners på kontakt@exitkompass.se, eller grunnlegger og partner Sture Stölen direkte på sture@exitkompass.se. Vurderer du å selge, kan du bestille et kostnadsfritt, konfidensielt møte med en partner – større selskaper får tilbudet direkte i resultatet.", "k": "kontakt kontakte e-post telefon møte bestille partner rådgiver"}, {"q": "Hvordan påvirker renten verdivurderingen?", "a": "Multiplene justeres for styringsrenten. Når renten er høy, blir finansiering dyrere og kjøpere betaler lavere multipler, og omvendt. Justeringen er maksimalt ±0,6x på multippelen.", "k": "rente styringsrente norges bank påvirker multippel"}, {"q": "Hvor nøyaktig er verdivurderingen?", "a": "Det er en indikativ verdivurdering basert på forenklede markedsmultipler og opplysningene som hentes eller oppgis. Den faktiske prisen avhenger av kjøperen, transaksjonsstrukturen, arbeidskapitalen og utfallet av due diligence. Se den som en første vurdering, ikke som en formell verdivurdering.", "k": "nøyaktig sikker treffsikker stemmer pålitelig indikativ"}, {"q": "Hva er selskapet mitt verdt?", "a": "I praksis er et selskap verdt det en kjøper er villig til å betale. For små og mellomstore unoterte selskaper tar man som regel utgangspunkt i driftsresultatet før avskrivninger (EBITDA) og multipliserer med en multippel som avhenger av bransje, størrelse og risiko. I Exitkompass ligger grunnmultiplene mellom ca. 4 og 8,5 ganger EBITDA avhengig av bransje, ifølge Dealsuite Nordic M&A Monitor, som sammenstiller nordiske M&A-rådgiveres transaksjoner. Mindre selskaper verdsettes lavere enn større, og deretter justeres det for selskapets egne styrker og svakheter.", "k": "verdt verdi verdsette verdivurdering"}, {"q": "Hvordan regner Exitkompass ut verdien?", "a": "Vi regner med tre multipler – EV/EBITDA, EV/EBIT og EV/omsetning – på et vektet gjennomsnitt av de siste årenes resultat, med justeringer for kundekonsentrasjon, andel gjentakende inntekter, eieravhengighet, vekst, avtaler og rapportering. Ved lave marginer veier omsetningen tyngre. Multiplene følger også rentenivået, konjunkturen og selskapets margin sammenlignet med næringen. Vi leser også teksten i årsregnskapet og revisjonsberetningen; for eksempel senker en presisering om fortsatt drift multippelen. Til slutt legges netto kontanter til for å få aksjeverdien.", "k": ""}, {"q": "Hvilke multipler bruker Exitkompass – EBITDA, EBIT eller omsetning?", "a": "Alle tre, fordi det er slik kjøpere regner ved oppkjøp. EV/EBITDA er vanligst for små og mellomstore selskaper. EV/EBIT gir et mer riktig bilde for kapitalkrevende selskaper med store avskrivninger, og EV/omsetning brukes når lønnsomheten er lav eller midlertidig svak. Resultatdelen vektes 60 % på EBITDA og 40 % på EBIT, og omsetningen får 20–50 % avhengig av marginen. I resultatet ser du multippelen og verdien for hver metode.", "k": ""}, {"q": "Hvordan verdsettes et aksjeselskap når man skal selge det?", "a": "Ved et salg verdsettes aksjeselskapet ut fra hva en kjøper er villig til å betale: det normaliserte resultatet de siste årene ganger en bransjemultippel, justert for risiko og kvalitet. Deretter legges kontantene til og rentebærende gjeld trekkes fra, så får man verdien av aksjene. Exitkompass regner dette ut gratis og viser hva som øker verdien før et salg.", "k": ""}, {"q": "Hva er forskjellen på selskapsverdi og aksjeverdi?", "a": "Selskapsverdien (enterprise value) er verdien av selve virksomheten, uavhengig av hvordan den er finansiert. Aksjeverdien er det eierne får: selskapsverdien pluss kontanter minus rentebærende gjeld. Exitkompass viser begge.", "k": ""}, {"q": "Hva øker verdien før et salg?", "a": "Kjøpere betaler mer for selskaper med spredte og gjentakende inntekter, som fungerer uten eieren, har skriftlige avtaler med kunder og nøkkelpersoner, vokser stabilt og har en tydelig og pålitelig finansiell rapportering. Exitkompass viser hvilke av disse tiltakene som betyr mest for akkurat ditt selskap.", "k": ""}, {"q": "Kan jeg bruke verdivurderingen ved skifte, arveoppgjør eller tvist?", "a": "Nei. Exitkompass er laget for salg og viser hva en kjøper kan tenkes å betale for selskapet, altså markedsverdien ved fortsatt drift basert på multipler. Ved skifte, arveoppgjør, tvister, innløsning av minoritetsaksjer eller skattesaker brukes ofte andre metoder, for eksempel substansverdi, og det kreves en formell verdivurdering. Vil du selge nå eller om noen år, er Exitkompass riktig verktøy.", "k": ""}, {"q": "Hvilke opplysninger trenger jeg?", "a": "Organisasjonsnummer eller selskapsnavn er nok til å komme i gang. For norske selskaper henter vi opplysninger fra Brønnøysundregistrene, og du kan laste opp årsregnskapene som PDF for en sikrere vurdering. Deretter svarer du på sju spørsmål om virksomheten.", "k": "trenger laste opp årsregnskap dokumenter underlag"}, {"q": "Hva koster det?", "a": "Hurtigvurderingen er gratis og krever ingen registrering. Den fullstendige rapporten koster 2 995 kr og rapport med gjennomgang sammen med en partner 6 995 kr, uten mva. Rapporten leveres innen 1–2 virkedager og faktureres sammen med rapporten med 10 dagers betalingsfrist.", "k": "pris priser kostnad koster betale gebyr gratis kroner"}, {"q": "Behandles opplysningene mine konfidensielt?", "a": "Ja. Det meste vi henter, som årsregnskap og regnskapstall, er offentlig informasjon. Det du selv fyller inn og dokumentene du laster opp, for eksempel forretningsplan, budsjett og månedsrapporter, brukes bare til å lage verdivurderingen din og deles aldri med noen. Du kan når som helst be oss slette dem.", "k": "trygge trygg sikker sikkert konfidensiell dokumenter dokumentene opplysninger data slette gdpr deles"}, {"q": "Bygger verdivurderingen på historiske tall eller på budsjett?", "a": "På historiske tall fra årsregnskapene, hvis ikke noe annet lastes opp. Laster du opp månedsrapporter, budsjett eller forretningsplan, vektes de inn i rapporten. Månedsrapportene gir de siste tolv månedene, som får størst vekt i resultatgrunnlaget. Budsjettet gir en vekstverdi som vektes inn med 20 %, pluss 5 % hvis en forretningsplan forklarer det og pluss 10 % hvis resultatet hittil i år følger budsjettet. Ligger resultatet mer enn 15 % etter, trekkes 10 % fra, og vokser budsjettet mye raskere enn historikken, halveres vekten. Vekten er høyst 35 %, fordi kjøpere først og fremst betaler for dokumentert resultat.", "k": "historiske historikk budsjett prognose forretningsplan månedsrapport månedsrapporter ltm vekst fremtid vekting vektes"}, {"q": "Passer Exitkompass for store selskaper og konsern?", "a": "Exitkompass er laget for små og mellomstore selskaper med omsetning opp til rundt 500 MNOK, der multipler for unoterte selskaper gir en rimelig første vurdering. Mindre konsern verdsettes på konserntallene. For større selskaper og konsern styres verdien av børsnoterte sammenlignbare selskaper og strategiske transaksjoner, så der viser verktøyet ingen automatisk verdivurdering, men tilbyr i stedet et kostnadsfritt møte med en partner i Adsco Capital Partners.", "k": "stort store størrelse konsern storselskap milliarder grense"}, {"q": "Fungerer Exitkompass for svenske selskaper?", "a": "Ja. Den svenske versjonen finnes på exitkompass.se og bruker svenske registeropplysninger fra Bolagsverket og svenske kroner.", "k": "sverige svensk svenske"}, {"q": "Koster det noe å verdsette selskapet?", "a": "Nei. Den indikative verdivurderingen i Exitkompass er gratis og krever ingen registrering. En fullstendig rapport kan bestilles mot betaling.", "k": ""}, {"q": "Hvor lang tid tar det?", "a": "Noen minutter. Tallene hentes automatisk, og du svarer på sju spørsmål om virksomheten.", "k": ""}, {"q": "Hvor mange ganger overskuddet er et selskap verdt?", "a": "Det avhenger av bransje, størrelse og risiko. Små unoterte selskaper selges ofte for omtrent 3–8 ganger EBITDA.", "k": ""}, {"q": "Regner man på resultat før eller etter skatt?", "a": "Kjøpere regner normalt på driftsresultatet, før finansposter og skatt: EBITDA eller EBIT. Da kan selskaper sammenlignes uavhengig av finansiering.", "k": ""}, {"q": "Hvor lang tid tar et selskapssalg?", "a": "En salgsprosess tar ofte seks til tolv måneder fra forberedelse til gjennomføring. Forberedelsene som øker verdien bør starte ett til to år før.", "k": ""}, {"q": "Hva koster det å selge et aksjeselskap?", "a": "Det avhenger av størrelse og kompleksitet. Rådgivere tar ofte et fast honorar og et suksesshonorar, i tillegg kommer kostnader til juridisk bistand og due diligence.", "k": ""}], "stop": ["jeg", "du", "vi", "dere", "de", "det", "den", "en", "et", "og", "at", "er", "som", "for", "på", "i", "av", "med", "til", "om", "hvordan", "hva", "hvilke", "hvilken", "hvilket", "kan", "skal", "har", "mitt", "min", "mine", "ditt", "din", "deres", "man", "når", "hvor", "hvorfor", "finnes", "får", "gjør", "blir", "eller", "også", "ikke", "så"]}, "EN": {"ui": {"btn": "Questions?", "title": "Ask Exitkompass", "hello": "Hi! I answer common questions about valuation, the report and how Exitkompass works. Type a question or pick a suggestion.", "ph": "Type your question…", "send": "Send", "close": "Close", "rel": "Related questions:", "sugg": "Common questions:", "none": "I can't find a reliable answer to that. Try rephrasing, pick one of the common questions, or email kontakt@exitkompass.se.", "note": "Automatic answers from our FAQ – not advice."}, "kb": [{"q": "How do you choose the multiples?", "a": "The base EV/EBITDA multiple per industry and the size adjustment come from the Dealsuite Nordic M&A Monitor, a half-yearly survey of Nordic M&A advisers on completed deals in companies with revenue of EUR 1–200 million. In the latest edition (August 2026), industry averages range from 3.8x (retail) to 7.9x (software), and the multiple rises with size: about 3.6x at EBITDA of EUR 0.2 million and 7.2x at EUR 10 million. Health care services and healthtech are Adsco's assessment, since Dealsuite reports healthcare and pharmaceuticals together. We then adjust for the company's characteristics: growth, earnings trend, owner dependency, management, customer concentration, recurring revenue, reporting, written contracts and risk flags in the annual report, as well as the policy rate (at most ±0.6x), the business cycle in the industry (±0.25x) and the margin compared with the industry according to Statistics Sweden or Statistics Norway. Those adjustments are Adsco's assessment. The multiple never goes below 2.0x. EV/EBIT is derived from the EBITDA multiple, EV/revenue has its own levels, and the methods are blended (earnings part 60% EBITDA and 40% EBIT, revenue 20–50% depending on margin). The Argos Index is shown as a comparison but does not affect the multiple.", "k": "choose chose chosen select multiple multiples base industry level how set determined where come from source dealsuite database basis"}, {"q": "How does Exitkompass work?", "a": "Choose the country, then enter the registration number or company name. We fetch the annual reports and fill in the figures. You check them and answer seven questions about customers, contracts, owner dependency and more. You then get a value range, an exit readiness score and the actions that raise the value most, straight away. It takes about three minutes.", "k": "work works how start begin steps use tool"}, {"q": "What is in the report?", "a": "The report is a PDF from Adsco Capital Partners with a point valuation and scenarios, sensitivity analysis, the multiple bridge and normalised EBITDA, all of the buyer's findings with actions, a 12–24 month value creation plan, strategic value, buyer types, deal structure, a due diligence checklist and the sale process. It is reviewed by a senior adviser and available in English.", "k": "report included contents pdf get"}, {"q": "How quickly do I get the report?", "a": "The report is delivered within 1–2 working days of ordering, reviewed by a senior adviser. You don't pay when ordering; an invoice is sent with the report with 10 days' payment terms.", "k": "delivery quickly when time days invoice payment pay long until report delivery time"}, {"q": "Which sources do you use?", "a": "Annual reports from Bolagsverket and key figures from Allabolag (UC AB) for Swedish companies, and the Brønnøysund Register Centre for Norwegian ones. Industry comparisons from Statistics Sweden and Statistics Norway, the business cycle from the National Institute of Economic Research and Statistics Norway, policy rates from the Riksbank and Norges Bank, and the market for unlisted companies from the Argos Index.", "k": "sources data where from statistics riksbank norges bank argos registry"}, {"q": "What is strategic value?", "a": "Strategic value is what a buyer may pay on top of the financial value when the company brings synergies, such as new customers, markets, products, technology or skills. Exitkompass rates strategic interest as low, moderate or high based on industry, recurring revenue, growth, margin, customer spread and active buyers. The premium is not included in the valuation and requires the right buyer.", "k": "strategic value synergy synergies strategic buyer premium"}, {"q": "What is EBITDA and normalised EBITDA?", "a": "EBITDA is operating profit before depreciation and amortisation. Normalised EBITDA adjusts for what will not recur under a new owner: one-off costs are added back and the owner's salary is adjusted to what an employed CEO would cost. Years are weighted 1:2:3, with the most weight on the latest.", "k": "ebitda normalised normalized normalisation operating profit depreciation owner salary"}, {"q": "Can I use it in English for a company in another country?", "a": "Yes. Choose the country with the flags at the top and the language in the language selector. Any combination works, and the full report can be delivered in English.", "k": "english language country swedish norwegian switch"}, {"q": "How do I reach Sture Stölen?", "a": "Sture Stölen is a founding partner of Adsco Capital Partners. You can reach him directly at sture@exitkompass.se.", "k": "sture stölen stølen stoelen founder founding partner email address"}, {"q": "How do I contact you?", "a": "You can reach Adsco Capital Partners at kontakt@exitkompass.se, or founding partner Sture Stölen directly at sture@exitkompass.se. If you are thinking about selling, you can book a free, confidential meeting with a partner – larger companies are offered this directly in the result.", "k": "contact email phone meeting book partner adviser advisor"}, {"q": "How do interest rates affect the valuation?", "a": "The multiples are adjusted for the policy rate. When rates are high, financing costs more and buyers pay lower multiples, and the other way round. The adjustment is at most ±0.6x on the multiple.", "k": "interest rate rates policy rate affect multiple"}, {"q": "How accurate is the valuation?", "a": "It is an indicative valuation based on simplified market multiples and the information fetched or provided. The actual price depends on the buyer, the deal structure, working capital and the outcome of due diligence. Treat it as a first assessment, not a formal valuation.", "k": "accurate accuracy reliable exact correct indicative"}, {"q": "What is my company worth?", "a": "In practice a company is worth what a buyer is willing to pay. For small and medium-sized unlisted companies the starting point is usually earnings before interest, tax, depreciation and amortisation (EBITDA) multiplied by a multiple that depends on industry, size and risk. In Exitkompass the base multiples range from about 4 to 8.5 times EBITDA depending on the industry, according to the Dealsuite Nordic M&A Monitor, which compiles deals reported by Nordic M&A advisers. Smaller companies are valued lower than larger ones, and the multiple is then adjusted for the company's own strengths and weaknesses.", "k": "worth value valuation valuing"}, {"q": "Is the valuation based on historical figures or on a budget?", "a": "On historical figures from the annual reports, unless you upload something else. If you upload monthly reports, a budget or a business plan, they are weighted into the report. The monthly reports give the last twelve months, which get the largest weight in the earnings base. The budget gives a growth value weighted in at 20%, plus 5% if a business plan explains it and plus 10% if results so far this year are on budget. If results are more than 15% behind, 10% is deducted, and if the budget grows much faster than history, the weight is halved. The weight is at most 35%, because buyers mainly pay for proven earnings.", "k": "historical history budget forecast business plan monthly reports ltm growth future weighting weighted"}, {"q": "Is Exitkompass suitable for large companies and groups?", "a": "Exitkompass is built for small and medium-sized companies with revenue up to about 50 million euros (500 million SEK or NOK), where multiples for unlisted companies give a reasonable first assessment. Smaller groups are valued on the consolidated figures. For larger companies and groups, value is driven by listed peers and strategic transactions, so the tool shows no automatic valuation there and instead offers a free meeting with a partner at Adsco Capital Partners.", "k": "large big size group groups consolidated billion limit enterprise"}, {"q": "Which countries does Exitkompass cover?", "a": "Sweden, Norway, Finland, the Netherlands, Poland and Lithuania. We fetch accounts from each national register: Bolagsverket and Allabolag in Sweden, the Brønnøysund Register Centre in Norway, the Finnish Patent and Registration Office (PRH), the Dutch Chamber of Commerce (KVK), the Polish National Court Register (KRS) and the Lithuanian Registry Centre. Small Dutch companies often file only a balance sheet, so you add revenue and EBITDA yourself. Amounts are shown in the local currency: SEK, NOK, PLN or euros. The tool is available in English, Swedish, Norwegian, Finnish, Dutch, Polish and Lithuanian, and you can choose any language for any country.", "k": "countries country sweden norway swedish norwegian"}, {"q": "Which multiples does Exitkompass use – EBITDA, EBIT or revenue?", "a": "All three, because that is how buyers calculate in acquisitions. EV/EBITDA is the most common for small and medium-sized companies. EV/EBIT gives a fairer picture for capital-intensive companies with large depreciation, and EV/revenue is used when profitability is low or temporarily weak. The earnings part is weighted 60% EBITDA and 40% EBIT, and revenue gets 20–50% depending on the margin.", "k": ""}, {"q": "What is the difference between enterprise value and equity value?", "a": "Enterprise value is the value of the business itself, regardless of how it is financed. Equity value is what the owners receive: enterprise value plus cash minus interest-bearing debt. Exitkompass shows both.", "k": ""}, {"q": "What raises the value before a sale?", "a": "Buyers pay more for companies with spread and recurring revenue, that run without the owner, have written contracts with customers and key people, grow steadily and have clear, reliable financial reporting. Exitkompass shows which of these actions matter most for your company.", "k": ""}, {"q": "Can I use the valuation for divorce, probate or a dispute?", "a": "No. Exitkompass is built for a sale and shows what a buyer might pay for the company, that is the going-concern market value based on multiples. Divorce, estate settlement, inheritance, disputes, minority buy-outs and tax matters often require other methods, such as net asset value, and a formal valuation.", "k": ""}, {"q": "What does it cost?", "a": "The quick valuation is free and needs no sign-up. The full report costs 2,995 SEK or NOK in Sweden and Norway, €490 in Finland and the Netherlands, 1,190 PLN in Poland and €290 in Lithuania. The report with a review by a partner costs 6,995 SEK or NOK, €1,190, 2,790 PLN or €690. Prices exclude VAT. The report is delivered within 1–2 working days and invoiced with 10 days' payment terms.", "k": "price prices pricing cost costs much fee free pay"}, {"q": "Is my information handled confidentially?", "a": "Yes. Most of what we fetch, such as annual reports and accounts, is public information. What you enter yourself and the documents you upload, such as a business plan, budget and monthly reports, are used only to produce your valuation and are never shared with anyone. You can ask us to delete them at any time.", "k": "safe secure security confidential private documents data delete gdpr shared privacy"}, {"q": "Do I need to upload anything?", "a": "Usually not. Enter the registration number (organisationsnummer) and the annual reports are fetched for you. If a report is not filed digitally, you can upload it as a PDF.", "k": "upload documents need annual report files"}, {"q": "Can I use the valuation for a divorce or an estate?", "a": "No. The valuation shows the value in a sale to a buyer. Divorce, estate settlement, disputes and tax matters often require a formal valuation using other methods.", "k": ""}, {"q": "What is a normal EBITDA multiple for a small company?", "a": "According to the Dealsuite Nordic M&A Monitor, the Nordic average is about 5.4x EBITDA, ranging from about 4x in retail to 8x in software and healthcare. Size matters a lot: around 3.6x for EBITDA of EUR 0.2 million versus about 7.2x for EUR 10 million.", "k": ""}, {"q": "Is the equity value the same as the price I get?", "a": "Not exactly. The final price also depends on the buyer, financing, due diligence, working capital and terms such as earn-outs or vendor notes.", "k": ""}, {"q": "How long does it take to sell a company in Norway?", "a": "Normally six to nine months from preparation to closing, longer if the company needs work before it is ready for buyers.", "k": ""}, {"q": "Who buys Norwegian SMEs?", "a": "Industry players, Nordic serial acquirers, private equity funds, private buyers and sometimes the management team. Each pays for different things.", "k": ""}], "stop": ["i", "you", "we", "they", "it", "the", "a", "an", "and", "to", "is", "are", "as", "for", "on", "in", "of", "with", "about", "how", "what", "which", "can", "should", "have", "has", "my", "mine", "your", "our", "do", "does", "get", "when", "where", "why", "there", "be", "or", "also", "not", "so"]}, "PL": {"ui": {"btn": "Pytania?", "title": "Zapytaj Exitkompass", "hello": "Cześć! Odpowiadam na najczęstsze pytania o wycenę, raport i działanie Exitkompass. Wpisz pytanie lub wybierz propozycję.", "ph": "Wpisz pytanie…", "send": "Wyślij", "close": "Zamknij", "rel": "Powiązane pytania:", "sugg": "Najczęstsze pytania:", "none": "Nie znam pewnej odpowiedzi na to pytanie. Spróbuj sformułować je inaczej, wybierz jedno z najczęstszych pytań albo napisz na kontakt@exitkompass.se.", "note": "Automatyczne odpowiedzi z naszych FAQ – nie stanowią porady."}, "kb": [{"q": "Jak działa Exitkompass?", "a": "Wpisz numer KRS lub NIP. Pobieramy dane spółki z KRS, a Ty wgrywasz sprawozdanie finansowe (XML z RDF), z którego odczytujemy dane. Sprawdzasz liczby i odpowiadasz na siedem pytań m.in. o klientów, umowy i zależność od właściciela. Od razu otrzymujesz przedział wartości, ocenę gotowości do sprzedaży i działania, które najbardziej podnoszą wartość. Trwa to ok. trzech minut.", "k": "działa jak zacząć start kroki korzystać narzędzie"}, {"q": "Dlaczego nie mogę wyszukać spółki po nazwie?", "a": "Publiczne API Krajowego Rejestru Sądowego wyszukuje tylko po numerze. Numer KRS lub NIP znajdziesz w wyszukiwarce KRS, na fakturze lub w stopce strony internetowej spółki.", "k": "nazwa nazwie wyszukać wyszukiwanie szukać znaleźć numer krs nip regon"}, {"q": "Co zawiera raport?", "a": "Raport to PDF po polsku od Adsco Capital Partners z wyceną punktową i scenariuszami, analizą wrażliwości, pomostem mnożnika i znormalizowaną EBITDA, wszystkimi ustaleniami kupującego z działaniami, planem wzrostu wartości na 12–24 miesiące, wartością strategiczną, typami kupujących, strukturą transakcji, listą kontrolną due diligence i procesem sprzedaży.", "k": "raport zawiera zawartość pdf otrzymam"}, {"q": "Jak szybko otrzymam raport?", "a": "Raport jest dostarczany w ciągu 1–2 dni roboczych od zamówienia. Nie płacisz przy zamówieniu; faktura jest wysyłana razem z raportem, z 10-dniowym terminem płatności.", "k": "dostawa szybko kiedy czas dni faktura płatność zapłacić"}, {"q": "Jakie źródła wykorzystujecie?", "a": "Dane spółki z Krajowego Rejestru Sądowego (Ministerstwo Sprawiedliwości), dla numeru NIP także z Wykazu podatników VAT (Ministerstwo Finansów), dane finansowe ze sprawozdań, które wgrywasz, stopę referencyjną z NBP, mnożniki branżowe z Dealsuite Nordic M&A Monitor z korektą dla Polski oraz rynek spółek niepublicznych z Argos Index.", "k": "źródła dane skąd krs nbp dealsuite argos rejestr"}, {"q": "Co to jest EBITDA i znormalizowana EBITDA?", "a": "EBITDA to zysk z działalności operacyjnej przed amortyzacją. Znormalizowana EBITDA koryguje to, co nie powtórzy się u nowego właściciela: koszty jednorazowe są doliczane, a wynagrodzenie właściciela korygowane do kosztu zatrudnionego prezesa. Lata mają wagi 1:2:3, z największą wagą dla ostatniego.", "k": "ebitda znormalizowana normalizacja zysk operacyjny amortyzacja wynagrodzenie właściciela"}, {"q": "Co to jest wartość strategiczna?", "a": "Wartość strategiczna to kwota, którą kupujący może zapłacić ponad wartość finansową, gdy spółka daje synergie, np. nowych klientów, rynki, produkty, technologię lub kompetencje. Premia nie jest wliczona w wycenę i wymaga właściwego kupującego.", "k": "wartość strategiczna synergia synergie kupujący strategiczny premia"}, {"q": "Jak stopy procentowe wpływają na wycenę?", "a": "Mnożniki są korygowane o stopę referencyjną NBP. Gdy stopy są wysokie, finansowanie jest droższe i kupujący płacą niższe mnożniki, i odwrotnie. Korekta wynosi maksymalnie ±0,6x.", "k": "stopy procentowe stopa referencyjna nbp odsetki wpływ mnożnik"}, {"q": "Jak dokładna jest wycena?", "a": "To orientacyjna wycena oparta na uproszczonych mnożnikach rynkowych i podanych informacjach. Rzeczywista cena zależy od kupującego, struktury transakcji, kapitału obrotowego i wyniku due diligence. Traktuj ją jako pierwszą ocenę, a nie formalną wycenę.", "k": "dokładna dokładność wiarygodna pewna orientacyjna"}, {"q": "Moja spółka składa sprawozdanie mikro – czy to działa?", "a": "Tak, ale sprawozdanie mikrojednostki nie pokazuje zysku operacyjnego ani amortyzacji. Odczytamy przychody, a EBITDA uzupełnisz w drugim kroku (zysk operacyjny plus amortyzacja z ksiąg).", "k": "mikro mikrojednostka mała jednostka uproszczone sprawozdanie"}, {"q": "Jak skontaktować się z Sture Stölenem?", "a": "Sture Stölen jest partnerem założycielem Adsco Capital Partners. Możesz napisać do niego bezpośrednio na sture@exitkompass.se (po angielsku).", "k": "sture stölen stolen partner założyciel e-mail adres kontakt"}, {"q": "Jak się z wami skontaktować?", "a": "Napisz do Adsco Capital Partners na kontakt@exitkompass.se. Rozmowy z partnerami prowadzimy po angielsku. Jeśli myślisz o sprzedaży, możesz umówić bezpłatne, poufne spotkanie z partnerem.", "k": "kontakt e-mail adres telefon spotkanie umówić partner doradca"}, {"q": "Ile jest warta moja firma?", "a": "W praktyce firma jest warta tyle, ile kupujący jest gotów za nią zapłacić. W przypadku małych i średnich spółek niepublicznych punktem wyjścia jest zwykle zysk przed odsetkami, podatkami i amortyzacją (EBITDA) pomnożony przez mnożnik zależny od branży, wielkości i ryzyka. Mnożnik jest następnie korygowany o mocne i słabe strony spółki. Mniejsze spółki wycenia się niżej niż większe.", "k": "warta wartość wycenić wycena"}, {"q": "Skąd pochodzą mnożniki dla polskich spółek?", "a": "Brak publicznego, regularnego badania mnożników transakcyjnych dla polskich MŚP. Dlatego wychodzimy od mnożników branżowych z Dealsuite Nordic M&A Monitor, badania transakcji raportowanych przez doradców M&A w krajach nordyckich, i obniżamy je dla Polski o 15% na podstawie oceny Adsco Capital Partners. Korekta jest pokazana jako osobny krok w pomoście mnożnika, więc widzisz jej wpływ.", "k": "mnożniki mnożnik dealsuite polska korekta transakcje"}, {"q": "Skąd wziąć sprawozdanie finansowe w formacie XML?", "a": "Spółki wpisane do KRS składają sprawozdania finansowe w formie elektronicznej (XML) do Repozytorium Dokumentów Finansowych. Otwórz Przeglądarkę Dokumentów Finansowych na stronie Ministerstwa Sprawiedliwości, wpisz numer KRS, przy pozycji „Roczne sprawozdanie finansowe” wybierz pobranie i wgraj plik w Exitkompass. Jeden plik zawiera dane za dwa lata. Plik możesz też otrzymać od swojej księgowej lub biura rachunkowego.", "k": "xml rdf sprawozdanie plik pobrać repozytorium przeglądarka dokumentów księgowa"}, {"q": "Czy wycena opiera się na danych historycznych, czy na budżecie?", "a": "Na danych historycznych ze sprawozdań finansowych, chyba że wgrasz coś więcej. Raporty miesięczne, budżet lub biznesplan uwzględniamy w raporcie. Raporty miesięczne dają ostatnie dwanaście miesięcy, które mają największą wagę w bazie wyników. Budżet daje wartość wzrostu z wagą 20%, plus 5%, jeśli wyjaśnia go biznesplan, i plus 10%, jeśli wyniki od początku roku są zgodne z budżetem. Waga wynosi maksymalnie 35%, ponieważ kupujący płacą głównie za udokumentowane wyniki.", "k": "historyczne budżet prognoza biznesplan raporty miesięczne ltm wzrost przyszłość waga"}, {"q": "Jakie mnożniki stosuje Exitkompass – EBITDA, EBIT czy przychody?", "a": "Wszystkie trzy, bo tak liczą kupujący przy przejęciach. EV/EBITDA jest najczęstszy dla małych i średnich spółek. EV/EBIT daje bardziej sprawiedliwy obraz spółek kapitałochłonnych z wysoką amortyzacją, a EV/przychody stosuje się, gdy rentowność jest niska lub przejściowo słaba. Część wynikowa to w 60% EBITDA i w 40% EBIT, a przychody mają wagę 20–50% w zależności od marży.", "k": ""}, {"q": "Czym różni się wartość przedsiębiorstwa od wartości kapitału własnego?", "a": "Wartość przedsiębiorstwa (EV) to wartość samej działalności, niezależnie od sposobu finansowania. Wartość kapitału własnego to to, co otrzymują właściciele: wartość przedsiębiorstwa plus środki pieniężne minus zadłużenie oprocentowane. Exitkompass pokazuje obie.", "k": ""}, {"q": "Co podnosi wartość firmy przed sprzedażą?", "a": "Kupujący płacą więcej za spółki z rozproszonymi i powtarzalnymi przychodami, które działają bez właściciela, mają pisemne umowy z klientami i kluczowymi pracownikami, rosną stabilnie i mają przejrzystą, wiarygodną sprawozdawczość. Exitkompass pokazuje, które z tych działań są najważniejsze dla Twojej spółki.", "k": ""}, {"q": "Czy mogę użyć wyceny do podziału majątku, spadku lub sporu?", "a": "Nie. Exitkompass służy do sprzedaży i pokazuje, ile kupujący może zapłacić za spółkę, czyli wartość rynkową przy kontynuacji działalności opartą na mnożnikach. Podział majątku, spadek, spory, wykup wspólników i sprawy podatkowe często wymagają innych metod, np. wyceny majątkowej, oraz formalnej wyceny.", "k": ""}, {"q": "Ile to kosztuje?", "a": "Szybka wycena jest bezpłatna i nie wymaga rejestracji. Pełny raport kosztuje 1 190 zł netto, a raport z omówieniem z partnerem 2 790 zł netto. Raport jest dostarczany w ciągu 1–2 dni roboczych i fakturowany z 10-dniowym terminem płatności.", "k": "cena ceny koszt kosztuje płacić opłata bezpłatnie darmowe zł złotych"}, {"q": "Czy moje dane są bezpieczne?", "a": "Tak. Dane z KRS są publiczne. To, co wpisujesz, i dokumenty, które wgrywasz, np. sprawozdania, biznesplan, budżet czy raporty miesięczne, wykorzystujemy wyłącznie do przygotowania Twojej wyceny i nikomu ich nie udostępniamy. W każdej chwili możesz poprosić o ich usunięcie.", "k": "bezpieczne bezpieczeństwo poufne poufność dokumenty dane usunąć rodo udostępniane"}], "stop": ["ja", "ty", "my", "wy", "oni", "to", "ten", "ta", "te", "jest", "są", "i", "a", "w", "z", "na", "do", "o", "od", "dla", "jak", "co", "czy", "jaki", "jaka", "jakie", "mogę", "można", "ma", "mam", "moja", "moje", "mój", "twoja", "nie", "się", "po", "przy", "też", "lub", "albo"]}, "LT": {"ui": {"btn": "Klausimai?", "title": "Klauskite Exitkompass", "hello": "Sveiki! Atsakau į dažniausius klausimus apie vertinimą, ataskaitą ir Exitkompass veikimą. Parašykite klausimą arba pasirinkite pasiūlymą.", "ph": "Parašykite klausimą…", "send": "Siųsti", "close": "Uždaryti", "rel": "Susiję klausimai:", "sugg": "Dažni klausimai:", "none": "Patikimo atsakymo neradau. Pabandykite suformuluoti kitaip, pasirinkite vieną iš dažnų klausimų arba rašykite kontakt@exitkompass.se.", "note": "Automatiniai atsakymai iš mūsų DUK – ne konsultacija."}, "kb": [{"q": "Kaip veikia Exitkompass?", "a": "Įveskite įmonės kodą arba pavadinimą. Iš Registrų centro atvirų duomenų paimame pajamas ir pelną už paskutinius trejus metus. Patikrinate skaičius, papildote EBITDA ir atsakote į septynis klausimus apie klientus, sutartis, priklausomybę nuo savininko ir kt. Iš karto gaunate vertės intervalą, pasirengimo pardavimui balą ir veiksmus, kurie labiausiai didina vertę. Tai užtrunka apie tris minutes.", "k": "veikia kaip pradėti žingsniai naudoti įrankis"}, {"q": "Ką apima ataskaita?", "a": "Ataskaita – tai PDF lietuvių kalba iš Adsco Capital Partners su taškiniu vertinimu ir scenarijais, jautrumo analize, daugiklio tiltu ir normalizuota EBITDA, visomis pirkėjo išvadomis su veiksmais, vertės didinimo planu 12–24 mėnesiams, strategine verte, pirkėjų tipais, sandorio struktūra, išsamaus patikrinimo kontroliniu sąrašu ir pardavimo procesu.", "k": "ataskaita apima turinys pdf gausiu"}, {"q": "Kaip greitai gausiu ataskaitą?", "a": "Ataskaita pateikiama per 1–2 darbo dienas nuo užsakymo. Užsakydami nemokate; sąskaita siunčiama kartu su ataskaita, apmokėjimo terminas – 10 dienų.", "k": "pristatymas greitai kada laikas dienos sąskaita mokėjimas mokėti"}, {"q": "Kokius šaltinius naudojate?", "a": "Įmonės duomenis ir finansinių ataskaitų rodiklius – iš Registrų centro ir Valstybinės mokesčių inspekcijos atvirų duomenų (data.gov.lt), palūkanų normą – iš Europos Centrinio Banko, sektorių daugiklius – iš Dealsuite Nordic M&A Monitor su korekcija Lietuvai, nebiržinių įmonių rinką – iš Argos Index.", "k": "šaltiniai duomenys iš kur registrų centras vmi ecb dealsuite argos registras"}, {"q": "Kas yra EBITDA ir normalizuota EBITDA?", "a": "EBITDA – tai veiklos pelnas prieš nusidėvėjimą ir amortizaciją. Normalizuota EBITDA koreguoja tai, kas nepasikartos naujam savininkui: vienkartinės išlaidos pridedamos atgal, o savininko atlyginimas koreguojamas iki samdomo vadovo kainos. Metams suteikiami svoriai 1:2:3, didžiausias – paskutiniams.", "k": "ebitda normalizuota normalizavimas veiklos pelnas nusidėvėjimas savininko atlyginimas"}, {"q": "Kas yra strateginė vertė?", "a": "Strateginė vertė – tai suma, kurią pirkėjas gali sumokėti virš finansinės vertės, kai įmonė suteikia sinergijų, pavyzdžiui, naujų klientų, rinkų, produktų, technologijų ar kompetencijų. Premija neįtraukta į vertinimą ir reikalauja tinkamo pirkėjo.", "k": "strateginė vertė sinergija sinergijos pirkėjas premija"}, {"q": "Kaip palūkanų normos veikia vertinimą?", "a": "Daugikliai koreguojami pagal ECB indėlių palūkanų normą. Kai palūkanos didelės, finansavimas brangesnis ir pirkėjai moka mažesnius daugiklius, ir atvirkščiai. Korekcija – ne daugiau kaip ±0,6x.", "k": "palūkanos palūkanų norma ecb poveikis daugiklis"}, {"q": "Kiek tikslus vertinimas?", "a": "Tai orientacinis vertinimas, pagrįstas supaprastintais rinkos daugikliais ir pateikta informacija. Faktinė kaina priklauso nuo pirkėjo, sandorio struktūros, apyvartinio kapitalo ir išsamaus patikrinimo rezultatų. Laikykite jį pirmuoju įvertinimu, o ne oficialiu vertinimu.", "k": "tikslus tikslumas patikimas tiksliai orientacinis"}, {"q": "Kaip susisiekti su Sture Stölen?", "a": "Sture Stölen yra Adsco Capital Partners partneris įkūrėjas. Jam galite rašyti tiesiogiai sture@exitkompass.se (anglų kalba).", "k": "sture stölen stolen partneris įkūrėjas el. paštas adresas kontaktai"}, {"q": "Kaip su jumis susisiekti?", "a": "Rašykite Adsco Capital Partners adresu kontakt@exitkompass.se. Pokalbius su partneriais vedame anglų kalba. Jei galvojate apie pardavimą, galite užsisakyti nemokamą, konfidencialų susitikimą su partneriu.", "k": "kontaktai el. paštas adresas telefonas susitikimas užsakyti partneris patarėjas"}, {"q": "Kiek verta mano įmonė?", "a": "Praktikoje įmonė verta tiek, kiek pirkėjas pasirengęs už ją sumokėti. Mažų ir vidutinių nebiržinių įmonių vertinimo atspirties taškas paprastai yra pelnas prieš palūkanas, mokesčius, nusidėvėjimą ir amortizaciją (EBITDA), padaugintas iš daugiklio, kuris priklauso nuo sektoriaus, dydžio ir rizikos. Daugiklis koreguojamas pagal įmonės stipriąsias ir silpnąsias puses. Mažesnės įmonės vertinamos mažiau nei didesnės.", "k": "verta vertė įvertinti vertinimas"}, {"q": "Iš kur Exitkompass gauna mano įmonės duomenis?", "a": "Iš Registrų centro Juridinių asmenų registro ir Valstybinės mokesčių inspekcijos atvirų duomenų, skelbiamų data.gov.lt: įmonės pavadinimas, pagrindinė veikla (EVRK) ir finansinių ataskaitų rodikliai – pardavimo pajamos, pelnas prieš apmokestinimą, grynasis pelnas, nuosavas kapitalas ir įsipareigojimai. Registras neskelbia veiklos pelno, nusidėvėjimo ir pinigų, todėl juos patikrinate ir įrašote patys.", "k": "registras registrų centras duomenys finansinės ataskaitos iš kur"}, {"q": "Kodėl EBITDA laukuose yra pelnas prieš apmokestinimą?", "a": "Viešai skelbiamose finansinių ataskaitų santraukose nėra nusidėvėjimo ir palūkanų sąnaudų, todėl kaip pradžią naudojame pelną prieš apmokestinimą. EBITDA = pelnas prieš apmokestinimą + palūkanų sąnaudos + nusidėvėjimas ir amortizacija. Šias sumas rasite savo finansinėse ataskaitose; jas pridėjus vertė dažnai gerokai padidėja.", "k": "ebitda pelnas prieš apmokestinimą nusidėvėjimas geltoni laukai"}, {"q": "Iš kur paimti daugikliai Lietuvos įmonėms?", "a": "Viešo, reguliaraus Lietuvos MVĮ sandorių daugiklių tyrimo nėra. Todėl remiamės Dealsuite Nordic M&A Monitor – Šiaurės šalių M&A patarėjų pateikiamų sandorių tyrimu – ir sumažiname daugiklius Lietuvai 15 % pagal Adsco Capital Partners vertinimą. Korekcija parodyta atskirai daugiklio tilte, todėl matote jos poveikį.", "k": "daugikliai daugiklis dealsuite lietuva korekcija sandoriai"}, {"q": "Ar vertinimas grindžiamas istoriniais duomenimis, ar biudžetu?", "a": "Istoriniais duomenimis, nebent įkelsite daugiau. Mėnesio ataskaitos, biudžetas ar verslo planas įvertinami ataskaitoje. Mėnesio ataskaitos parodo paskutinius dvylika mėnesių, kuriems suteikiamas didžiausias svoris. Biudžetas suteikia augimo vertę su 20 % svoriu, plius 5 %, jei jį paaiškina verslo planas, ir plius 10 %, jei šių metų rezultatai atitinka biudžetą. Didžiausias svoris – 35 %, nes pirkėjai daugiausia moka už įrodytus rezultatus.", "k": "istoriniai biudžetas prognozė verslo planas mėnesio ataskaitos ltm augimas ateitis svoris"}, {"q": "Kuo skiriasi įmonės vertė nuo nuosavo kapitalo vertės?", "a": "Įmonės vertė (EV) – tai pačios veiklos vertė, nepriklausomai nuo finansavimo. Nuosavo kapitalo vertė – tai, ką gauna savininkai: įmonės vertė plius pinigai minus palūkanų skola. Exitkompass rodo abi.", "k": ""}, {"q": "Kas padidina įmonės vertę prieš pardavimą?", "a": "Pirkėjai moka daugiau už įmones su išsklaidytomis ir pasikartojančiomis pajamomis, kurios veikia be savininko, turi rašytines sutartis su klientais ir pagrindiniais darbuotojais, stabiliai auga ir turi aiškią, patikimą atskaitomybę. Exitkompass parodo, kurie veiksmai svarbiausi jūsų įmonei.", "k": ""}, {"q": "Ar galiu naudoti vertinimą turto padalijimui, paveldėjimui ar ginčui?", "a": "Ne. Exitkompass skirtas pardavimui ir parodo, kiek pirkėjas galėtų sumokėti už įmonę, t. y. rinkos vertę veiklos tęstinumo prielaida pagal daugiklius. Turto padalijimui, paveldėjimui, ginčams, išpirkimui ir mokesčių klausimams dažnai reikia kitų metodų ir oficialaus vertinimo.", "k": ""}, {"q": "Kiek tai kainuoja?", "a": "Greitas vertinimas nemokamas ir nereikalauja registracijos. Išsami ataskaita kainuoja 290 € be PVM, o ataskaita su aptarimu su partneriu – 690 € be PVM. Ataskaita pateikiama per 1–2 darbo dienas, sąskaita apmokama per 10 dienų.", "k": "kaina kainos kainuoja mokėti mokestis nemokamai eurų"}, {"q": "Ar mano duomenys saugūs?", "a": "Taip. Registro duomenys yra vieši. Tai, ką įrašote, ir įkeltus dokumentus, pavyzdžiui, finansines ataskaitas, verslo planą, biudžetą ar mėnesio ataskaitas, naudojame tik jūsų vertinimui ir su niekuo nesidalijame. Bet kada galite paprašyti juos ištrinti.", "k": "saugūs saugumas konfidencialu dokumentai duomenys ištrinti bdar dalijamasi"}], "stop": ["aš", "tu", "mes", "jūs", "jie", "tai", "tas", "ta", "ir", "o", "bet", "kad", "yra", "buvo", "į", "iš", "su", "be", "ant", "apie", "kaip", "kas", "ar", "koks", "kokia", "kokie", "galiu", "galima", "mano", "jūsų", "man", "ne", "per", "pagal", "už", "prie", "taip", "pat", "arba"]}, "NL": {"ui": {"btn": "Vragen?", "title": "Vraag het Exitkompass", "hello": "Hallo! Ik beantwoord veelgestelde vragen over de waardering, het rapport en hoe Exitkompass werkt. Typ uw vraag of kies een suggestie.", "ph": "Typ uw vraag…", "send": "Versturen", "close": "Sluiten", "rel": "Gerelateerde vragen:", "sugg": "Veelgestelde vragen:", "none": "Ik vond geen betrouwbaar antwoord. Probeer het anders te formuleren, kies een veelgestelde vraag of mail naar kontakt@exitkompass.se.", "note": "Automatische antwoorden uit onze FAQ – geen advies."}, "kb": [{"q": "Hoe werkt Exitkompass?", "a": "Vul het KVK-nummer in. We halen de laatst gedeponeerde jaarrekening op uit de open data van de KVK. U controleert de cijfers, vult omzet en EBITDA aan en beantwoordt zeven vragen over klanten, contracten, afhankelijkheid van de eigenaar en meer. U krijgt direct een waardebandbreedte, een exit-score en de acties die de waarde het meest verhogen. Het duurt ongeveer drie minuten.", "k": "werkt hoe beginnen stappen gebruiken tool"}, {"q": "Wat staat er in het rapport?", "a": "Het rapport is een PDF in het Nederlands van Adsco Capital Partners met een puntwaardering en scenario's, een gevoeligheidsanalyse, de multiplebrug en de genormaliseerde EBITDA, alle bevindingen van de koper met acties, een waardeverhogingsplan voor 12–24 maanden, de strategische waarde, kopertypen, dealstructuur, een due-diligencechecklist en het verkoopproces.", "k": "rapport inhoud pdf krijg bevat"}, {"q": "Hoe snel krijg ik het rapport?", "a": "Het rapport wordt binnen 1–2 werkdagen na de bestelling geleverd. U betaalt niets bij het bestellen; de factuur wordt met het rapport verstuurd, betaaltermijn 10 dagen.", "k": "levering snel wanneer tijd dagen factuur betaling betalen"}, {"q": "Welke bronnen gebruiken jullie?", "a": "Cijfers uit gedeponeerde jaarrekeningen uit de open data van de Kamer van Koophandel, de rente van de Europese Centrale Bank, sectormultiples uit de Dealsuite Nordic M&A Monitor met een correctie voor Nederland, en de markt voor niet-beursgenoteerde bedrijven uit de Argos Index.", "k": "bronnen gegevens waar vandaan kvk ecb dealsuite argos register"}, {"q": "Wat is EBITDA en genormaliseerde EBITDA?", "a": "EBITDA is het bedrijfsresultaat vóór afschrijvingen. De genormaliseerde EBITDA corrigeert voor wat bij een nieuwe eigenaar niet terugkomt: eenmalige kosten worden opgeteld en het DGA-salaris wordt gecorrigeerd naar de kosten van een ingehuurde directeur. De jaren wegen 1:2:3, het zwaarst het laatste jaar.", "k": "ebitda genormaliseerd normalisatie bedrijfsresultaat afschrijvingen dga salaris"}, {"q": "Wat is strategische waarde?", "a": "Strategische waarde is wat een koper boven de financiële waarde kan betalen als het bedrijf synergieën oplevert, zoals nieuwe klanten, markten, producten, technologie of competenties. De premie zit niet in de waardering en vraagt de juiste koper.", "k": "strategische waarde synergie synergieën koper premie"}, {"q": "Hoe beïnvloedt de rente de waardering?", "a": "De multiples worden gecorrigeerd voor de depositorente van de ECB. Bij een hoge rente is financiering duurder en betalen kopers lagere multiples, en andersom. De correctie is maximaal ±0,6x.", "k": "rente ecb effect multiple renteniveau"}, {"q": "Hoe nauwkeurig is de waardering?", "a": "Het is een indicatieve waardering op basis van vereenvoudigde marktmultiples en de aangeleverde informatie. De werkelijke prijs hangt af van de koper, de dealstructuur, het werkkapitaal en de due diligence. Zie het als een eerste inschatting, niet als een formele waardering.", "k": "nauwkeurig betrouwbaar precies indicatief"}, {"q": "Hoe neem ik contact op met Sture Stölen?", "a": "Sture Stölen is oprichtend partner van Adsco Capital Partners. U kunt hem direct mailen op sture@exitkompass.se (in het Engels).", "k": "sture stölen stolen partner oprichter e-mail adres contact"}, {"q": "Hoe neem ik contact met jullie op?", "a": "Mail Adsco Capital Partners op kontakt@exitkompass.se. Gesprekken met de partners voeren we in het Engels. Denkt u aan verkoop, dan kunt u een gratis, vertrouwelijk gesprek met een partner plannen.", "k": "contact e-mail adres telefoon gesprek afspraak partner adviseur"}, {"q": "Wat is mijn bedrijf waard?", "a": "In de praktijk is een bedrijf waard wat een koper ervoor wil betalen. Voor niet-beursgenoteerde mkb-bedrijven is het vertrekpunt meestal de winst vóór rente, belastingen en afschrijvingen (EBITDA), vermenigvuldigd met een multiple die afhangt van sector, omvang en risico. De multiple wordt gecorrigeerd voor de sterke en zwakke punten van het bedrijf. Kleinere bedrijven worden lager gewaardeerd dan grotere.", "k": "waard waarde waarderen waardering"}, {"q": "Waar haalt Exitkompass de cijfers van mijn bedrijf vandaan?", "a": "Uit de open data van de Kamer van Koophandel over gedeponeerde jaarrekeningen (KVK Handelsregister Open Dataset Jaarrekeningen). Daarin staat alleen wat het bedrijf heeft gedeponeerd: bij kleine bedrijven vaak alleen een verkorte balans, bij middelgrote bedrijven ook het bedrijfsresultaat en vaak de brutomarge. Afschrijvingen staan er niet in, dus omzet en EBITDA controleert en vult u zelf aan.", "k": "kvk register gegevens jaarrekening waar vandaan"}, {"q": "Waarom staat er geen omzet bij mijn bedrijf?", "a": "Kleine en micro-ondernemingen mogen een verkorte jaarrekening deponeren zonder winst-en-verliesrekening, en middelgrote bedrijven mogen de brutomarge vermelden in plaats van de omzet. Neem de cijfers dan over uit de volledige jaarrekening van uw accountant. Heeft u alleen de winst of alleen de omzet, dan waardeert Exitkompass op wat er is.", "k": "omzet ontbreekt verkort balans micro klein winst-en-verliesrekening brutomarge"}, {"q": "Waar komen de multiples voor Nederlandse bedrijven vandaan?", "a": "Er is geen openbaar, regelmatig onderzoek naar multiples van Nederlandse mkb-transacties. We gaan daarom uit van de Dealsuite Nordic M&A Monitor, een onderzoek onder Scandinavische M&A-adviseurs, en verhogen de multiples voor Nederland met 10% op basis van de beoordeling van Adsco Capital Partners: de Nederlandse M&A-markt is groter en liquider, met veel strategische kopers en private-equityfondsen. De correctie staat apart in de multiplebrug, zodat u het effect ziet.", "k": "multiples multiple dealsuite nederland correctie transacties"}, {"q": "Is de waardering gebaseerd op historische cijfers of op de begroting?", "a": "Op historische cijfers, tenzij u meer uploadt. Maandrapportages, een begroting of een businessplan worden in het rapport meegewogen. Maandrapportages geven de laatste twaalf maanden, die het zwaarst wegen. Een begroting geeft een groeiwaarde met een gewicht van 20%, plus 5% als een businessplan haar onderbouwt en plus 10% als de resultaten van dit jaar op koers liggen. Het maximum is 35%, omdat kopers vooral betalen voor aangetoonde resultaten.", "k": "historisch begroting prognose businessplan maandrapportages ltm groei toekomst gewicht"}, {"q": "Wat is het verschil tussen ondernemingswaarde en aandelenwaarde?", "a": "De ondernemingswaarde (EV) is de waarde van het bedrijf zelf, los van de financiering. De aandelenwaarde is wat de eigenaren krijgen: de ondernemingswaarde plus liquide middelen min rentedragende schulden. Exitkompass toont beide.", "k": ""}, {"q": "Wat verhoogt de waarde van een bedrijf vóór de verkoop?", "a": "Kopers betalen meer voor bedrijven met gespreide en terugkerende omzet, die zonder de eigenaar draaien, schriftelijke contracten met klanten en sleutelmedewerkers hebben, stabiel groeien en een heldere, betrouwbare rapportage hebben. Exitkompass laat zien welke acties voor uw bedrijf het belangrijkst zijn.", "k": ""}, {"q": "Kan ik de waardering gebruiken voor een echtscheiding, erfenis of geschil?", "a": "Nee. Exitkompass is bedoeld voor verkoop en laat zien wat een koper voor het bedrijf zou kunnen betalen: de marktwaarde op going-concernbasis op basis van multiples. Voor een boedelverdeling, erfenis, geschil, uitkoop of fiscale vragen zijn vaak andere methoden en een formele waardering nodig.", "k": ""}, {"q": "Wat kost het?", "a": "De snelle waardering is gratis en zonder registratie. Het volledige rapport kost € 490 excl. btw en het rapport met een bespreking met een partner € 1.190 excl. btw. Het rapport wordt binnen 1–2 werkdagen geleverd; de factuur heeft een betaaltermijn van 10 dagen.", "k": "prijs prijzen kost kosten betalen tarief gratis euro"}, {"q": "Zijn mijn gegevens veilig?", "a": "Ja. De KVK-gegevens zijn openbaar. Wat u invult en de documenten die u uploadt, zoals de jaarrekening, een businessplan, begroting of maandrapportages, gebruiken we alleen voor uw waardering en delen we met niemand. U kunt op elk moment vragen ze te verwijderen.", "k": "veilig veiligheid vertrouwelijk documenten gegevens verwijderen avg delen"}], "stop": ["ik", "jij", "je", "u", "wij", "we", "zij", "het", "de", "een", "en", "of", "maar", "dat", "is", "was", "in", "van", "met", "zonder", "op", "over", "hoe", "wat", "wie", "welke", "kan", "mag", "mijn", "uw", "me", "niet", "voor", "door", "bij", "ook", "te", "er", "dit", "die"]}, "FI": {"ui": {"btn": "Kysymyksiä?", "title": "Kysy Exitkompassilta", "hello": "Hei! Vastaan yleisiin kysymyksiin arvonmäärityksestä, raportista ja Exitkompassin toiminnasta. Kirjoita kysymyksesi tai valitse ehdotus.", "ph": "Kirjoita kysymyksesi…", "send": "Lähetä", "close": "Sulje", "rel": "Aiheeseen liittyvät kysymykset:", "sugg": "Usein kysyttyä:", "none": "En löytänyt luotettavaa vastausta. Kokeile muotoilla toisin, valitse jokin usein kysytyistä tai kirjoita osoitteeseen kontakt@exitkompass.se.", "note": "Automaattiset vastaukset UKK:sta – ei neuvontaa."}, "kb": [{"q": "Miten Exitkompass toimii?", "a": "Kirjoita yrityksen nimi tai Y-tunnus. Haemme tiedot ja digitaalisen tilinpäätöksen PRH:n avoimesta datasta. Tarkistat luvut ja vastaat seitsemään kysymykseen asiakkaista, sopimuksista, omistajariippuvuudesta ja muusta. Saat heti arvohaarukan, myyntivalmiuspisteet ja arvoa eniten nostavat toimenpiteet. Se kestää noin kolme minuuttia.", "k": "toimii miten aloittaa vaiheet käyttää työkalu"}, {"q": "Mitä raportti sisältää?", "a": "Raportti on suomenkielinen PDF Adsco Capital Partnersilta: piste-estimaatti ja skenaariot, herkkyysanalyysi, kerroinsilta ja normalisoitu EBITDA, kaikki ostajan havainnot toimenpiteineen, arvonnostosuunnitelma 12–24 kuukaudelle, strateginen arvo, ostajatyypit, kaupan rakenne, due diligence -tarkistuslista ja myyntiprosessi.", "k": "raportti sisältö pdf saan sisältää"}, {"q": "Kuinka nopeasti saan raportin?", "a": "Raportti toimitetaan 1–2 arkipäivässä tilauksesta. Tilatessa et maksa mitään; lasku lähetetään raportin mukana, maksuaika 10 päivää.", "k": "toimitus nopeasti milloin aika päivää lasku maksu maksaa"}, {"q": "Mitä lähteitä käytätte?", "a": "Yritystiedot ja digitaaliset tilinpäätökset Patentti- ja rekisterihallituksen avoimesta datasta, koron Euroopan keskuspankilta, toimialakertoimet Dealsuite Nordic M&A Monitorista ja listaamattomien yritysten markkinan Argos Indexistä.", "k": "lähteet tiedot mistä prh ytj ekp dealsuite argos rekisteri"}, {"q": "Mikä on EBITDA ja normalisoitu EBITDA?", "a": "EBITDA on liikevoitto ennen poistoja. Normalisoitu EBITDA oikaisee sen, mikä ei toistu uudelle omistajalle: kertaluonteiset kulut lisätään takaisin ja omistajan palkka oikaistaan palkatun toimitusjohtajan kustannukseen. Vuodet painotetaan 1:2:3, eniten viimeisintä.", "k": "ebitda normalisoitu normalisointi liikevoitto poistot omistajan palkka"}, {"q": "Mitä on strateginen arvo?", "a": "Strateginen arvo on se, mitä ostaja voi maksaa taloudellisen arvon päälle, kun yritys tuo synergioita, kuten uusia asiakkaita, markkinoita, tuotteita, teknologiaa tai osaamista. Preemio ei sisälly arvioon ja edellyttää oikeaa ostajaa.", "k": "strateginen arvo synergia synergiat ostaja preemio"}, {"q": "Miten korot vaikuttavat arvioon?", "a": "Kertoimia oikaistaan EKP:n talletuskoron mukaan. Kun korot ovat korkealla, rahoitus on kalliimpaa ja ostajat maksavat matalampia kertoimia, ja päinvastoin. Oikaisu on enintään ±0,6x.", "k": "korko korot ekp vaikutus kerroin korkotaso"}, {"q": "Kuinka tarkka arvio on?", "a": "Se on suuntaa antava arvio yksinkertaistettujen markkinakertoimien ja toimitettujen tietojen perusteella. Todellinen hinta riippuu ostajasta, kaupan rakenteesta, käyttöpääomasta ja due diligencen tuloksista. Pidä sitä ensimmäisenä arviona, ei virallisena arvonmäärityksenä.", "k": "tarkka tarkkuus luotettava suuntaa antava"}, {"q": "Miten saan yhteyden Sture Stöleniin?", "a": "Sture Stölen on Adsco Capital Partnersin perustajapartneri. Voit lähettää hänelle sähköpostia suoraan osoitteeseen sture@exitkompass.se (englanniksi tai ruotsiksi).", "k": "sture stölen stolen partneri perustaja sähköposti osoite yhteystiedot"}, {"q": "Miten otan teihin yhteyttä?", "a": "Lähetä sähköpostia Adsco Capital Partnersille osoitteeseen kontakt@exitkompass.se. Keskustelemme englanniksi tai ruotsiksi. Jos harkitset myyntiä, voit varata maksuttoman, luottamuksellisen tapaamisen partnerin kanssa.", "k": "yhteys sähköposti osoite puhelin tapaaminen varata partneri neuvonantaja"}, {"q": "Mitä yritykseni on arvoinen?", "a": "Käytännössä yritys on arvoinen sen, mitä ostaja on valmis siitä maksamaan. Listaamattomien pk-yritysten arvonmäärityksen lähtökohta on yleensä tulos ennen korkoja, veroja ja poistoja (EBITDA) kerrottuna kertoimella, joka riippuu toimialasta, koosta ja riskistä. Kerrointa oikaistaan yrityksen vahvuuksien ja heikkouksien mukaan. Pienemmät yritykset arvostetaan alemmas kuin suuremmat.", "k": "arvoinen arvo arvioida arvonmääritys arvostus"}, {"q": "Mistä Exitkompass saa yritykseni tiedot?", "a": "Patentti- ja rekisterihallituksen (PRH) avoimesta datasta: yrityksen nimi, päätoimiala ja digitaalisesti ilmoitetun tilinpäätöksen luvut, kuten liikevaihto, liikevoitto, poistot, oma pääoma, rahavarat ja lainat rahoituslaitoksilta. Vain digitaalisesti (XBRL) ilmoitetut tilinpäätökset ovat saatavilla; muissa tapauksissa syötät luvut itse tai lataat tilinpäätöksen.", "k": "prh ytj rekisteri tiedot tilinpäätös mistä"}, {"q": "Miksi tilinpäätöksen lukuja ei löytynyt?", "a": "Moni pieni yritys ilmoittaa tilinpäätöksensä PRH:lle edelleen PDF-muodossa, eikä niiden lukuja ole avoimessa datassa. Digitaalinen ilmoittaminen yleistyy joka vuosi. Syötä siinä tapauksessa liikevaihto ja EBITDA itse tai lataa tilinpäätös.", "k": "puuttuu pdf digitaalinen xbrl ei löytynyt luvut tilinpäätös"}, {"q": "Mistä suomalaisten yritysten kertoimet tulevat?", "a": "Dealsuite Nordic M&A Monitorista, pohjoismaisten M&A-neuvonantajien kyselystä toteutuneista kaupoista. Suomi kuuluu kyselyn otokseen, ja suomalaiset pk-yritykset myydään samankaltaisilla tasoilla kuin muissa Pohjoismaissa, joten maakohtaista oikaisua ei tehdä.", "k": "kertoimet kerroin dealsuite suomi oikaisu kaupat"}, {"q": "Perustuuko arvio historiallisiin lukuihin vai budjettiin?", "a": "Historiallisiin lukuihin, ellet lataa lisää. Kuukausiraportit, budjetti tai liiketoimintasuunnitelma otetaan huomioon raportissa. Kuukausiraportit antavat viimeiset kaksitoista kuukautta, jotka painavat eniten. Budjetti antaa kasvuarvon 20 %:n painolla, lisäksi 5 %, jos liiketoimintasuunnitelma perustelee sen, ja 10 %, jos kuluvan vuoden tulokset ovat budjetissa. Enimmäispaino on 35 %, koska ostajat maksavat ensisijaisesti osoitetuista tuloksista.", "k": "historiallinen budjetti ennuste liiketoimintasuunnitelma kuukausiraportit ltm kasvu tulevaisuus paino"}, {"q": "Mikä on yritysarvon ja osakkeiden arvon ero?", "a": "Yritysarvo (EV) on liiketoiminnan arvo rahoituksesta riippumatta. Osakkeiden arvo on se, minkä omistajat saavat: yritysarvo plus rahavarat miinus korolliset velat. Exitkompass näyttää molemmat.", "k": ""}, {"q": "Mikä nostaa yrityksen arvoa ennen myyntiä?", "a": "Ostajat maksavat enemmän yrityksistä, joiden liikevaihto on hajautettua ja toistuvaa, jotka toimivat ilman omistajaa, joilla on kirjalliset sopimukset asiakkaiden ja avainhenkilöiden kanssa, jotka kasvavat vakaasti ja joilla on selkeä, luotettava raportointi. Exitkompass näyttää, mitkä toimenpiteet ovat yrityksellesi tärkeimmät.", "k": ""}, {"q": "Voiko arviota käyttää ositukseen, perintöön tai riitaan?", "a": "Ei. Exitkompass on tarkoitettu myyntiin ja näyttää, mitä ostaja voisi maksaa yrityksestä, eli markkina-arvon jatkuvuusperiaatteella kertoimien perusteella. Ositukseen, perintöön, riitoihin, lunastuksiin ja verotukseen tarvitaan usein muita menetelmiä ja virallinen arvonmääritys.", "k": ""}, {"q": "Mitä se maksaa?", "a": "Pika-arvio on maksuton eikä vaadi rekisteröitymistä. Täydellinen raportti maksaa 490 € (alv 0 %) ja raportti partnerin läpikäynnin kanssa 1 190 € (alv 0 %). Raportti toimitetaan 1–2 arkipäivässä, laskun maksuaika on 10 päivää.", "k": "hinta hinnat maksaa maksu kustannus ilmainen maksuton euroa"}, {"q": "Ovatko tietoni turvassa?", "a": "Kyllä. PRH:n tiedot ovat julkisia. Syöttämiäsi tietoja ja lataamiasi asiakirjoja, kuten tilinpäätöksiä, liiketoimintasuunnitelmaa, budjettia tai kuukausiraportteja, käytämme vain arvonmääritykseesi emmekä jaa niitä kenellekään. Voit milloin tahansa pyytää niiden poistamista.", "k": "turvassa turvallisuus luottamuksellinen asiakirjat tiedot poistaa gdpr jakaa"}], "stop": ["minä", "sinä", "hän", "me", "te", "he", "se", "ne", "ja", "tai", "mutta", "että", "on", "oli", "olla", "ei", "en", "et", "kun", "jos", "niin", "kuin", "mikä", "mitä", "miten", "missä", "mistä", "mihin", "kuka", "voiko", "voinko", "onko", "minun", "sinun", "teidän", "myös", "vain", "jo"]}}, API = "https://script.google.com/macros/s/AKfycbydGqgEqDXsMncViCZqfQ5beeTejorGbt4u0vxOcY9-0NJLA68ddxB6HXecPnBf336eAg/exec", DEF = D[window.EK_QB_DEF] ? window.EK_QB_DEF : Object.keys(D)[0];
  /* Questions asked in this chat are sent once, as one summary, when the visitor closes the bot or leaves the page. */
  let log = [], sentN = 0;
  function flush() {
    if (log.length <= sentN) return;
    const items = log.slice(sentN, sentN + 25); sentN = log.length;
    const body = JSON.stringify({ fn: "botLog", args: [{ lang: L(), page: location.pathname, items }] });
    try { if (!(navigator.sendBeacon && navigator.sendBeacon(API, body))) fetch(API, { method: "POST", body, keepalive: true, mode: "no-cors" }); } catch (e) {}
  }
  addEventListener("pagehide", flush);
  document.addEventListener("visibilitychange", () => { if (document.visibilityState === "hidden") flush(); });
  const L = () => { try { if (typeof lang !== "undefined" && D[lang]) return lang; } catch (e) {} return DEF; };
  const $ = id => document.getElementById(id);
  const norm = s => s.toLowerCase().replace(/[^\p{L}\p{N}%]+/gu, " ");
  const stem = w => w.length > 5 ? w.replace(/(arna|erna|orna|ene|ane|ing|ingen|ens|ets|en|et|er|ar|or|na|es|ed|s)$/, "") : w;
  const toks = (s, l) => norm(s).split(" ").filter(w => w && w.length > 1 && !D[l].stop.includes(w)).map(stem);
  let built = {};
  function index(l) {
    if (built[l]) return built[l];
    return built[l] = D[l].kb.map(e => ({ e, q: new Set(toks(e.q, l)), k: new Set(toks(e.k, l)), a: new Set(toks(e.a, l)) }));
  }
  function match(text, l) {
    const qt = toks(text, l); if (!qt.length) return [];
    const hit = (set, w) => set.has(w) || (w.length >= 5 && [...set].some(x => x.length >= 5 && (x.startsWith(w.slice(0, 5)) || w.startsWith(x.slice(0, 5)))));
    return index(l).map(x => {
      let s = 0;
      for (const w of qt) { if (hit(x.q, w)) s += 3; if (hit(x.k, w)) s += 3; if (hit(x.a, w)) s += 1; }
      return { e: x.e, s: s / Math.sqrt(qt.length) };
    }).filter(x => x.s >= 2.1).sort((a, b) => b.s - a.s);
  }
  function msg(cls, html) { const d = document.createElement("div"); d.className = "qb-m " + cls; d.innerHTML = html; $("qb-log").appendChild(d); $("qb-log").scrollTop = 1e9; return d; }
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
  function chips(label, list) {
    if (!list.length) return;
    const d = document.createElement("div"); d.className = "qb-chips";
    d.innerHTML = "<small>" + esc(label) + "</small>";
    list.forEach(e => { const b = document.createElement("button"); b.type = "button"; b.textContent = e.q; b.onclick = () => answer(e.q, e); d.appendChild(b); });
    $("qb-log").appendChild(d); $("qb-log").scrollTop = 1e9;
  }
  function answer(text, exact) {
    const l = L(), u = D[l].ui;
    msg("qb-me", esc(text));
    const rec = { q: text };
    const r = exact ? [{ e: exact }].concat(match(text, l).filter(x => x.e !== exact)) : match(text, l);
    if (!r.length) { log.push(Object.assign(rec, { m: "", ok: false })); msg("qb-bot", esc(u.none)); chips(u.sugg, D[l].kb.slice(0, 4)); return; }
    log.push(Object.assign(rec, { m: r[0].e.q, ok: true }));
    msg("qb-bot", "<strong>" + esc(r[0].e.q) + "</strong>" + esc(r[0].e.a));
    chips(u.rel, r.slice(1, 3).map(x => x.e));
  }
  let shownFor = "";
  function labels() {
    const l = L(), u = D[l].ui;
    $("qb-btnt").textContent = u.btn; $("qb-t").textContent = u.title; $("qb-x").setAttribute("aria-label", u.close); $("qb-x").textContent = "×";
    $("qb-in").placeholder = u.ph; $("qb-in").setAttribute("aria-label", u.ph); $("qb-send").textContent = u.send; $("qb-note").textContent = u.note;
    if (shownFor !== l && !$("qb").hidden) greet();
  }
  function greet() { const l = L(); shownFor = l; $("qb-log").innerHTML = ""; msg("qb-bot", esc(D[l].ui.hello)); chips(D[l].ui.sugg, D[l].kb.slice(0, 4)); }
  $("qb-btn").onclick = () => { labels(); $("qb").hidden = false; $("qb-btn").hidden = true; if (shownFor !== L()) greet(); $("qb-in").focus(); };
  const close = () => { flush(); $("qb").hidden = true; $("qb-btn").hidden = false; $("qb-btn").focus(); };
  $("qb-x").onclick = close;
  document.addEventListener("keydown", e => { if (e.key === "Escape" && !$("qb").hidden) close(); });
  $("qb-f").onsubmit = e => { e.preventDefault(); const t = $("qb-in").value.trim(); if (!t) return; $("qb-in").value = ""; answer(t); };
  labels();
  document.addEventListener("click", e => { if (e.target.closest && e.target.closest("[data-lang],#lang-sel")) setTimeout(labels, 50); });
  document.addEventListener("change", e => { if (e.target && e.target.id === "lang-sel") setTimeout(labels, 50); });
})();
